mapper.select:
SELECT device_info_id, device_info_org_id, device_info_name, device_info_vendor, device_info_model, device_info_category, device_info_sub_category, device_info_ip, device_info_port, device_info_username, device_info_password, device_info_online, device_info_serial, device_info_firmware, device_info_channel_count, device_info_latitude, device_info_longitude, device_info_address, device_info_offline_threshold, device_info_code, device_info_external_id, device_info_credential_id, device_info_owner_id, device_info_owner_name, device_info_owner_dept, device_info_owner_phone, device_info_source, device_info_stream_main_url, device_info_stream_sub_url, device_info_last_online_at, device_info_last_offline_at, device_info_install_at, device_info_warranty_end, device_info_area, device_info_tags, device_info_status, device_info_remark, device_info_version, create_name, create_by, create_time, update_time, update_name, update_by FROM device_info
AND ( device_info_name LIKE CONCAT('%', #{q.keyword}, '%') OR device_info_code LIKE CONCAT('%', #{q.keyword}, '%') OR device_info_ip LIKE CONCAT('%', #{q.keyword}, '%') OR device_info_serial LIKE CONCAT('%', #{q.keyword}, '%') OR device_info_owner_name LIKE CONCAT('%', #{q.keyword}, '%') )
AND device_info_org_id = #{q.orgId}
AND device_info_vendor = #{q.vendor}
AND device_info_category = #{q.category}
AND device_info_sub_category = #{q.subCategory}
AND device_info_online = #{q.online}
AND device_info_status = #{q.status}
AND device_info_owner_id = #{q.ownerId}
AND device_info_tags LIKE CONCAT('%', #{q.tag}, '%')
ORDER BY
device_info_name create_time device_info_last_online_at update_time
ASC DESC

SELECT COUNT(*) AS total, COUNT(CASE WHEN device_info_online = 1 THEN 1 END) AS online, COUNT(CASE WHEN device_info_online = 0 OR device_info_online IS NULL THEN 1 END) AS offline, COUNT(CASE WHEN device_info_latitude IS NULL OR device_info_longitude IS NULL OR device_info_latitude = 0 OR device_info_longitude = 0 THEN 1 END) AS no_location FROM device_info
AND device_info_org_id = #{orgId}
AND device_info_vendor = #{vendor}
